function config(x={}){const d=clone(DEFAULT_CONFIG);for(const k of Object.keys(x))if(!['uncertainty','profileRules','environment'].includes(k))d[k]=clone(x[k]);Object.assign(d.uncertainty,x.uncertainty||{});Object.assign(d.profileRules,x.profileRules||{});if(x.environment)d.environment={...d.environment,...clone(x.environment),ratios:{...d.environment.ratios,...(x.environment.ratios||{})}};return validateConfig(d);}
function validateRules(p){if(p.rules==null)return;if(typeof p.rules!=='object')fail('Drivlineregler för '+p.id+' ska vara ett objekt.');for(const [group,values] of Object.entries(p.rules)){if(!['energy','kwh','body','maint','battery'].includes(group))fail('Okänd drivlineregel '+group+' för '+p.id);for(const [type,v] of Object.entries(values||{})){if(!DRIVES.includes(type))fail('Okänd drivlina '+type+' i regel för '+p.id);finite(v,'Regel '+p.id+' '+group+' '+type,0,group==='battery'?1000:10);}}}
function validateConfig(c){
 finite(c.year,'År',1900,2200);finite(c.iterations,'Antal simuleringar',100,30000);finite(c.seed,'Slumptalsfrö',0,4294967295);finite(c.electricity,'Elens klimatfaktor',0,2000);finite(c.batteryEF,'Batterifaktor',0,1000);finite(c.chargeEfficiency,'Laddverkningsgrad',.1,1);finite(c.phevElectric,'Laddhybridens elandel',0,1);finite(c.trafficChange,'Trafikförändring',-.99,5);finite(c.electrify,'Ökad elandel',0,1);for(const k of ['energyScale','productionScale','lifeScale'])finite(c[k],k,.01,10);
 for(const [k,v] of Object.entries(c.profileRules))finite(v,'Drivlinjeregel '+k,0,k==='phevBatteryMax'?1000:10);
 if(![c.year,c.seed,c.iterations].every(Number.isInteger))fail('År, antal simuleringar och frö ska vara heltal.');
 if(!['calibrated','network'].includes(c.mode))fail('Okänt beräkningsläge.');
 const env=c.environment;if(!env||typeof env.enabled!=='boolean')fail('Miljöfaktorer saknas.');finite(env.urbanShare,'Tätortsandel',0,1);for(const p of PROFILES)finite(env.ratios?.[p.id],'Stad/landsbygd-kvot '+p.id,.2,5);
 for(const [k,v] of Object.entries(c.uncertainty))finite(v,'Osäkerhet '+k,0,k==='mixConcentration'?100000:3);
 if(c.uncertainty.mixConcentration<1)fail('Mixkoncentration ska vara minst 1.');
 if(!Array.isArray(c.profiles)||c.profiles.length!==7)fail('Sju fordonsklasser krävs.');
 const ids=new Set();for(const [pi,p] of c.profiles.entries()){if(ids.has(p.id)||p.id!==PROFILES[pi].id)fail('Fordonsklassernas ID och ordning ska behållas.');ids.add(p.id);if(p.group!==PROFILES.find(q=>q.id===p.id).group)fail('Ändra inte kalibreringsgrupp.');for(const k of ['life','body','battery','maint','eol','credit','mj','kwh','other'])finite(p[k],p.id+' '+k,k==='life'?1:0);validateRules(p);let s=0;for(const [k,v] of Object.entries(p.mix)){if(!DRIVES.includes(k))fail('Okänd drivlina '+k);s+=finite(v,'Mix '+p.id,0,1);}if(Math.abs(s-1)>1e-5)fail('Fordonsmixen för '+p.name+' ska summera till 100 %.');}
 for(const f of ['petrol','diesel','hvo','biogas']){if(!c.fuels[f])fail('Bränsle saknas.');for(const k of ['fossil','ttw','wtt','bio','bioCO2'])finite(c.fuels[f][k],f+' '+k,0,k==='fossil'?1:1000);}
 /* Scenario per område. Saknas listorna är scenariot oförändrat. */
 if(c.areaChanges!=null){if(!Array.isArray(c.areaChanges)||c.areaChanges.length>500)fail('Områdesändringarna ska vara en lista.');for(const a of c.areaChanges){if(!a||!['deso','district'].includes(a.level)||!a.id||!a.city)fail('Områdesändring saknar nivå, kommun eller område.');finite(a.change,'Trafikändring i '+a.id,-1,5);}}
 if(c.newRoads!=null){if(!Array.isArray(c.newRoads)||c.newRoads.length>500)fail('Nya vägar ska vara en lista.');for(const r of c.newRoads){if(!r||!r.city||!r.deso)fail('Ny väg saknar kommun eller DeSO.');if(!ROAD_DEFAULTS[String(r.roadClass||'').replace(/_link$/,'')])fail('Okänd vägtyp för ny väg: '+r.roadClass);finite(r.km,'Längd för ny väg',0,1000);if(r.aadt!=null)finite(r.aadt,'ÅDT för ny väg',0,300000);}}
 /* Områdesscenario: de boendes biltrafik på DeSO:ns vägar, räknad ur modell B. Saknas listan är scenariot oförändrat. */
 if(c.areaTraffic!=null){if(!Array.isArray(c.areaTraffic)||c.areaTraffic.length>50)fail('De boendes trafik ska vara en lista.');for(const t of c.areaTraffic){if(!t||!t.city||!t.deso)fail('De boendes trafik saknar kommun eller DeSO.');finite(t.carVkm,'Ändrat trafikarbete för boende i '+t.deso,-1e9,1e9);}}
 return c;
}
